	// 表
	// GetTableInfo 获取表信息
	GetTableInfo(context.Context, *GetTableInfoReq) (*GetTableInfoRsp, error)
	// 模板
	// GetTableTemplates 获取表模板信息
	GetTableTemplates(context.Context, *GetTableTemplatesReq) (*GetTableTemplatesRsp, error)
	// CreateTableTemplate 创建模板
