	// GetTableColumns 获取表列
	GetTableColumns(context.Context, *GetTableColumnsReq) (*GetTableColumnsRsp, error)
	// GetTableRows 获取表行
	GetTableRows(context.Context, *GetTableRowsReq) (*GetTableRowsRsp, error)
